import "dotenv/config";
import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";
import { users } from "./schema";

// Seeds the same two users that used to be hardcoded in `users.ts`, so a
// fresh database behaves the same as the old in-memory version out of the box.
async function main() {
  const connectionString = process.env.DATABASE_URL;
  if (!connectionString) {
    throw new Error("DATABASE_URL is not set. Copy .env.example to .env.local first.");
  }

  const sql = postgres(connectionString, { max: 1 });
  const db = drizzle(sql);

  console.log("Seeding users...");
  await db
    .insert(users)
    .values([
      { email: "ada@example.com", name: "Ada", createdAt: new Date("2026-01-04") },
      { email: "grace@example.com", name: "Grace", createdAt: new Date("2026-02-11") },
    ])
    .onConflictDoNothing({ target: users.email });
  console.log("Seed complete.");

  await sql.end();
}

main().catch((err) => {
  console.error("Seed failed:", err);
  process.exit(1);
});

