import { asc, eq } from "drizzle-orm";
import { db } from "./db/client";
import { users as usersTable } from "./db/schema";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

function toUser(row: typeof usersTable.$inferSelect): User {
  return {
    id: row.id,
    email: row.email,
    name: row.name,
    createdAt: row.createdAt.toISOString(),
  };
}

export async function listUsers(): Promise<User[]> {
  const rows = await db.select().from(usersTable).orderBy(asc(usersTable.createdAt));
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const [row] = await db.select().from(usersTable).where(eq(usersTable.id, id)).limit(1);
  return row ? toUser(row) : undefined;
}

// TODO: there is no real session handling yet — the dashboard just picks the first user.
export async function getCurrentUser(): Promise<User | undefined> {
  const [row] = await db
    .select()
    .from(usersTable)
    .orderBy(asc(usersTable.createdAt))
    .limit(1);
  return row ? toUser(row) : undefined;
}

